-- ============================================================
-- SEED EXT 5: Módulo 16 — Advanced Articles (ex 171-248)
-- Novos tópicos: artigos em TOEFL essays avançados, artigos com
-- proper nouns complexos, artigos em abstract/generic contexts,
-- artigos com quantifiers e superlatives
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'articles-advanced';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo articles-advanced não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 51: Artigos com substantivos abstratos e genéricos
  (cid,51,171,'gap_fill','_____ democracy requires not only _____ free and fair elections but also _____ strong civil society, _____ independent judiciary, and _____ government that is accountable to _____ people it governs.','Democracy (zero) / free (zero) / a / an / a / the',NULL,'Generic ''democracy'' = zero article. Indefinite articles for institutional types. ''The people it governs'' = specific group.','hard'),
  (cid,51,172,'gap_fill','_____ inequality is multidimensional: it encompasses _____ income inequality, _____ wealth inequality, and _____ inequality in _____ access to _____ education, _____ healthcare, and _____ political power.','Inequality (zero) / zero / zero / zero / zero / zero / zero / zero / zero',NULL,'Abstract concepts used generically: all zero article. ''Access to education/healthcare/political power'' = generic.','hard'),
  (cid,51,173,'multiple_choice','Which sentence uses articles CORRECTLY for a TOEFL essay introduction about technology?','Technology has transformed communication; the internet in particular has enabled connections that were unimaginable a century ago.','[''A technology has transformed communication; an internet has enabled connections.'',''The technology has transformed communication; the internet in particular has enabled connections.'',''Technology has transformed communication; the internet in particular has enabled connections that were unimaginable a century ago.'',''Technology has transformed communication; internet has enabled connections.'']','Generic ''Technology'' = zero. ''The internet'' = unique specific thing (known shared reference). ''A century'' = indefinite.','hard'),
  (cid,51,174,'gap_fill','_____ capitalism has generated extraordinary _____ wealth over _____ past two centuries, but _____ distribution of that wealth _____ (remain) profoundly unequal, raising _____ fundamental questions about _____ justice and _____ fairness.','Capitalism (zero) / wealth (zero) / the / the distribution / remains / fundamental (zero) / justice (zero) / fairness (zero)',NULL,'Generic -isms: zero. ''The past'' = definite time period. ''The distribution'' = specific known entity.','hard'),
  (cid,51,175,'gap_fill','_____ globalization _____ (not/be) _____ uniform process; its effects _____ (vary) substantially across _____ sectors, _____ regions, and _____ social groups, benefiting some while marginalizing _____ others.','Globalization (zero) / is not / a / vary / sectors (zero) / regions (zero) / social groups (zero) / others (zero)',NULL,'Generic concept + ''a uniform process'' (indefinite, classifying). Zero article for generic plurals.','hard'),

  -- BLOCK 52: Artigos com substantivos próprios complexos
  (cid,52,176,'gap_fill','_____ United Kingdom''s departure from _____ European Union fundamentally altered _____ terms of _____ UK''s participation in _____ single market and _____ customs union.','The / the / the / the / the / the',NULL,'Political entities: The United Kingdom, The European Union, the single market, the customs union = all require ''the.''','medium'),
  (cid,52,177,'gap_fill','_____ World Bank and _____ International Monetary Fund were established at _____ Bretton Woods conference in 1944 to provide _____ institutional architecture for _____ postwar international economic order.','The / the / the / an / the',NULL,'''The World Bank/IMF'' = specific institutions. ''The Bretton Woods conference'' = specific unique event. ''An institutional architecture'' = indefinite classification.','hard'),
  (cid,52,178,'multiple_choice','Which sentence uses articles with PROPER NOUNS correctly?','The Amazon Basin contains the world''s largest tropical rainforest and is home to an estimated ten percent of all species on Earth.','[''Amazon Basin contains world''s largest tropical rainforest.'',''The Amazon Basin contains the world''s largest tropical rainforest and is home to an estimated ten percent of all species on Earth.'',''A Amazon Basin contains the world''s largest tropical rainforest.'',''Amazon Basin contains the world''s largest tropical rainforest.'']','''The Amazon Basin'' = geographic feature with ''the.'' ''The world''s largest'' = superlative + specific. ''An estimated'' = indefinite modifier.','medium'),
  (cid,52,179,'gap_fill','_____ Sub-Saharan Africa _____ (face) _____ unique combination of _____ development challenges: _____ rapid population growth, _____ fragile statehood, _____ climate vulnerability, and _____ limited access to _____ international capital markets.','Sub-Saharan Africa (no article) / faces / a / development challenges (zero) / rapid (zero) / fragile (zero) / climate (zero) / limited (zero) / the',NULL,'''Sub-Saharan Africa'' = no article (region name without ''the''). ''A unique combination'' = indefinite. ''The international capital markets'' = specific known market.','hard'),
  (cid,52,180,'gap_fill','_____ Marshall Plan, announced by _____ United States Secretary of State in _____ 1948, provided _____ financial assistance that _____ (help) rebuild _____ war-devastated economies of _____ Western Europe.','The / the / zero (year) / financial (zero) / helped / the / the',NULL,'''The Marshall Plan'' = specific named plan. ''The Secretary of State'' = specific role. Year: no article. ''The war-devastated economies of Western Europe'' = specific set.','hard'),

  -- BLOCK 53: Artigos com superlatives e quantifiers
  (cid,53,181,'gap_fill','_____ most significant challenge facing _____ international climate negotiations is not _____ scientific uncertainty — that _____ (long/resolve/passive) — but rather _____ political will to act at _____ scale that _____ evidence demands.','The / zero (abstract) / scientific (zero) / has long been resolved / the / the / the',NULL,'''The most significant'' = superlative definite. Zero for abstract ''scientific uncertainty.'' ''The political will'' = specific contextual.','hard'),
  (cid,53,182,'gap_fill','Of _____ various policy instruments available, _____ carbon tax _____ (represent) _____ most economically efficient approach, though _____ implementation _____ (face) _____ significant political obstacles.','the / a / represents / the / its / faces / significant (zero)',NULL,'''The various'' = specific known set. ''A carbon tax'' = category. ''The most efficient'' = superlative definite. ''Its implementation'' = anaphoric definite.','hard'),
  (cid,53,183,'multiple_choice','Which sentence uses articles with SUPERLATIVES correctly?','The most comprehensive study to date has been conducted across twelve countries and involved over 50,000 participants.','[''A most comprehensive study to date has been conducted.'',''The most comprehensive study to date has been conducted across twelve countries and involved over 50,000 participants.'',''Most comprehensive study to date has been conducted.'',''The most comprehensive study to date has been conducted in twelve countries.'']','''The most comprehensive'' = superlative always takes ''the.'' ''Twelve countries'' = indefinite count. ''Over 50,000'' = indefinite.','easy'),
  (cid,53,184,'gap_fill','Both _____ theoretical and _____ empirical literature _____ (suggest) that _____ relationship between X and Y is mediated by _____ institutional context, though _____ precise mechanisms _____ (remain) poorly understood.','the / the / suggest / the / zero (abstract) / the precise / remain',NULL,'''The theoretical and empirical literature'' = specific bodies of literature. ''The relationship'' = specific known. ''The precise mechanisms'' = specific.','hard'),

  -- BLOCK 54: Artigos em tipos textuais específicos
  (cid,54,185,'production','[TOEFL Writing — 100 words] Write an academic paragraph on environmental degradation. Use articles with great precision throughout.','',NULL,'Environmental degradation has become one of the defining crises of the twenty-first century, threatening the ecological systems on which human civilization depends. The rapid loss of biodiversity, the acidification of the oceans, and the degradation of topsoil represent challenges of a different order from those that previous generations faced, because they threaten the fundamental planetary systems that underpin all economic and social activity. A comprehensive policy response will require pricing environmental externalities accurately, investing in restoration of degraded ecosystems, and reforming the agricultural and industrial practices responsible for the most severe damage. The scale of the challenge is such that incremental reform is insufficient; only a fundamental transformation of the relationship between the economy and the natural environment will suffice.','hard'),
  (cid,54,186,'gap_fill','In _____ academic writing, _____ use of _____ definite article before _____ concepts that _____ (previously/introduce/passive) in _____ text signals that _____ reader _____ (expect) _____ recognize _____ reference without _____ further explanation.','academic (zero) / the / the / concepts / have previously been introduced / the / the / is expected to / to / the / further (zero)',NULL,'Meta-discourse on articles: generic ''academic writing'' (zero) + specific textual references with ''the.''','hard'),
  (cid,54,187,'multiple_choice','In headlines, which article usage is CORRECT?','Government Launches New Initiative to Address Housing Crisis','[''The Government Launches the New Initiative to Address the Housing Crisis'',''Government Launches New Initiative to Address Housing Crisis'',''A Government Launches a New Initiative to Address a Housing Crisis'',''Government has Launched New Initiative to Address Housing Crisis'']','Headlines: zero article for most nouns (economy of space). ''Housing crisis'' = zero in headline style (but ''the housing crisis'' in body text).','medium'),
  (cid,54,188,'gap_fill','_____ key finding of _____ analysis is that _____ countries with _____ higher levels of _____ social trust _____ (tend) to achieve better outcomes across _____ wide range of _____ governance indicators.','The / the / countries (zero) / higher (zero) / social trust (zero) / tend / a / governance (zero)',NULL,'''The key finding of the analysis'' = specific. Zero for generic country category. ''A wide range'' = indefinite. ''Governance indicators'' = generic plural.','hard'),

  -- BLOCK 55: TOEFL Reading avançado com artigos
  (cid,55,189,'multiple_choice','[TOEFL Reading] ''A new approach has been developed that may transform the field.'' What does ''a new approach'' signal about subsequent mentions?','On first mention, ''a new approach'' = indefinite (introduced for the first time). Subsequent mentions will use ''the approach.''','[''It will always be called ''a new approach'''',''On first mention, ''a new approach'' = indefinite (introduced for the first time). Subsequent mentions will use ''the approach.'''',''''A'' signals the approach is not important'',''''A'' is used because the approach is unknown to science'']','The indefinite article introduces new information; ''the'' is used once the referent is established in the text.','easy'),
  (cid,55,190,'gap_fill','[TOEFL Reading] ''_____ evidence suggests that _____ relationship between _____ economic growth and _____ environmental quality follows _____ inverted U-curve known as _____ Environmental Kuznets Curve.'' Best articles?','The / the / zero (generic) / zero (generic) / an / the',NULL,'''The evidence'' (specific body cited). ''The relationship'' (specific discussed). Generic abstracts: zero. ''An inverted U-curve'' = indefinite classification. ''The Environmental Kuznets Curve'' = specific named concept.','hard'),
  (cid,55,191,'multiple_choice','[TOEFL Reading] ''The internet has revolutionized the way people access information.'' Why does ''the internet'' take ''the''?','The internet is treated as a unique, globally shared system — there is only one internet, making it a definite specific reference.','[''All technologies take ''the'''',''The internet is treated as a unique, globally shared system — there is only one internet, making it a definite specific reference.'',''''The'' is used for recent inventions'',''''The'' is used because ''internet'' starts with a vowel sound'']','Unique things that everyone knows and that exist in a singular definitive form = ''the.''','easy'),

  -- BLOCK 56: TOEFL Speaking avançado com artigos
  (cid,56,192,'production','[TOEFL Speaking — 45s] A reading discusses the rise of nationalism. Use precise article choices throughout your summary.','',NULL,'The reading examines the resurgence of nationalism as a political force in a number of countries that had previously appeared to be moving toward greater regional and international integration. According to the reading, the resurgence of nationalist sentiment reflects a combination of factors: the economic anxieties generated by globalization, the cultural dislocations associated with rapid demographic change, and the perceived failure of international institutions to deliver on their promises to broad populations. The reading argues that nationalism as a political ideology tends to become stronger during periods of economic insecurity, because it offers a simple explanatory framework — attributing complex problems to foreign competition, immigration, or international agreements — that is easier for people experiencing hardship to accept than the more complex explanations that economists and political scientists offer. The reading concludes that the future of the international liberal order depends on whether mainstream political leaders can address the legitimate grievances that fuel nationalism without reinforcing the exclusionary aspects of nationalist identity politics.','hard'),
  (cid,56,193,'production','[TOEFL Speaking — 45s] Discuss the role of the state in the economy. Use precise article choices throughout.','',NULL,'The relationship between the state and the market is one of the oldest and most contested questions in political economy, and the appropriate balance between them has been debated since the industrial revolution. The classical liberal tradition argued that the market, when allowed to function freely, allocates resources more efficiently than any central authority can; the state''s role, on this view, is to protect property rights, enforce contracts, and provide a small number of public goods that markets cannot supply. However, experience has demonstrated that unregulated markets generate significant market failures — externalities, information asymmetries, and monopoly power — that require active state intervention to correct. The question, then, is not whether the state should play a role in the economy, but what kind of role is most conducive to achieving both efficiency and equity. The evidence from the most successful economies suggests that a capable, accountable state — one that invests in public goods, regulates effectively, and provides social insurance — is a complement to the market rather than an alternative to it.','hard'),

  -- BLOCK 57: TOEFL Writing avançado com artigos
  (cid,57,194,'production','[TOEFL Writing — 200 words] Write a paragraph on urbanization and poverty using precise article choices.','',NULL,'The relationship between urbanization and poverty is more complex than either the pessimistic view of cities as concentrators of deprivation or the optimistic view of the city as an engine of opportunity suggests. The informal settlements that house a significant fraction of urban populations in developing countries — sometimes called slums, though the diversity of these communities resists simple categorization — are simultaneously places of exploitation and of aspiration. A household that moves from a rural village to an urban informal settlement may simultaneously experience worsening physical housing conditions and significantly higher cash income, access to a far wider range of services, and the opportunity for children to attend school of a quality unavailable in the area of origin. The urban poor face a distinctive set of vulnerabilities: access to land and the security of tenure that supports investment in housing improvements is often absent; exposure to environmental hazards — flooding, poor air quality, industrial pollution — is frequently higher than in wealthier urban areas; and the social networks that provide mutual support in communities of origin may not yet have been rebuilt in the urban context. Understanding the specific challenges of urban poverty is essential for designing interventions that address the conditions under which the poorest urban residents actually live.','hard'),
  (cid,57,195,'production','[TOEFL Writing — 200 words] Write a paragraph on the history of public health using precise article choices.','',NULL,'The history of public health is in significant part the history of collective responses to the recognition that health outcomes are shaped not only by individual biology and behavior but by the physical, social, and economic environments in which people live. The sanitary movement of the nineteenth century established the foundational insight that clean water, adequate sewage disposal, and decent housing were prerequisites for population health, well before the germ theory of disease was developed to explain the mechanisms involved. The introduction of widespread vaccination changed the trajectory of diseases that had caused mass mortality throughout human history, and the eradication of smallpox in 1980 represented the most significant achievement in the history of disease control. The public health model that emerged over the course of the twentieth century increasingly recognized that the determinants of health extended far upstream from the healthcare system into the conditions of work, housing, education, and economic security; the concept of the social determinants of health, developed systematically from the 1970s onward, provided the theoretical framework for this broader understanding. Today, the challenge is applying these insights to the new disease burden: the chronic non-communicable diseases — cardiovascular disease, cancer, diabetes, and mental illness — that now account for the majority of the global burden of disease but whose prevention requires sustained engagement with the social and economic conditions that generate them.','hard'),

  -- BLOCK 58: Final
  (cid,58,196,'production','[TOEFL Writing — 200 words] Write a paragraph on the global financial system using precise article choices.','',NULL,'The global financial system is simultaneously one of the most powerful engines of economic development and one of the most significant sources of systemic risk in the modern world economy. The system''s capacity to mobilize savings from across the globe and allocate them to their most productive uses has supported economic growth at a scale that would have been impossible without deep international financial integration. However, the same interconnectedness that generates these efficiency gains also creates the channels through which financial distress can spread rapidly across borders, as the global financial crisis of 2008 demonstrated with devastating clarity. The architecture of international financial governance — centered on the Bank for International Settlements, the Financial Stability Board, and the International Monetary Fund — has been substantially reformed since the crisis, with higher capital requirements, more robust stress-testing regimes, and improved mechanisms for managing the failure of systemically important financial institutions. Yet the system remains vulnerable in ways that the reforms may not have fully addressed: the rapid growth of non-bank financial intermediation, the increasing complexity of financial products, and the persistence of global imbalances all represent potential sources of instability. The fundamental challenge of governing a system that is global in its reach but regulated primarily by national authorities has not been resolved.','hard'),
  (cid,58,197,'production','[TOEFL Speaking — 60s] Discuss the role of education in economic development. Use precise article choices throughout.','',NULL,'The relationship between education and economic development has been studied extensively, and the evidence consistently supports the view that investment in education is one of the most powerful drivers of long-term economic growth available to policymakers. The returns to education at the individual level are well-documented: an additional year of schooling is associated with a significant increase in earnings, and this premium has been relatively stable across a wide range of countries and time periods. At the aggregate level, the countries that have made the most sustained investments in the quality and accessibility of education — the East Asian economies, the Scandinavian countries, and several middle-income countries that have invested heavily in human capital as a component of a broader development strategy — have consistently achieved better economic outcomes than comparable countries that neglected this dimension of development policy. However, the relationship between education and development is not automatic: the quality of education matters enormously, and systems that enroll large numbers of students without ensuring that they develop genuine cognitive skills and practical competencies generate credentials without the underlying human capital development that drives productivity. The evidence also suggests that the returns to education are strongest when the broader economic environment provides employment opportunities for educated workers; in economies with severe structural underemployment, educational investment can generate frustration and political instability rather than the economic dividends the theory predicts.','hard'),
  (cid,58,198,'production','[TOEFL Writing — Final 200 words] Write a paragraph on the role of civil society in democracy using precise article choices throughout.','',NULL,'Civil society — the sphere of voluntary associations, non-governmental organizations, social movements, and informal networks that exists between the state and the market — plays an essential role in the functioning of democratic governance. The organizations that comprise civil society perform several distinct functions: they aggregate and articulate the interests and concerns of citizens who might not otherwise have access to formal political processes; they monitor the exercise of public power and hold governments and corporations accountable to the commitments they have made; they provide services in areas where the state is absent or inadequate; and they nurture the habits of deliberation, compromise, and civic engagement that democratic culture requires. The health of a democracy can be read to a significant degree in the vigor and independence of its civil society: the countries in which independent civil society organizations can operate freely, criticize the government without fear of repression, and organize citizens across lines of partisan identity tend to have more accountable, responsive governance than those in which the state seeks to control or suppress civil society activity. The pressures on civil society in many countries are intensifying: the proliferation of legal restrictions on civil society funding, registration, and activity represents a deliberate strategy by governments that prefer to govern without effective accountability. Defending the space in which civil society can operate freely is therefore not simply a matter of associational freedom — it is a prerequisite for democracy itself.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
